    vector<long long> w(n);
    for (int i = 0; i < n; ++i) {
        cin >> w[i];
    }

    vector<vector<pair<int, int>>> adj(n);
    for (int i = 0; i < n - 1; ++i) {
        int u, v, l;
        cin >> u >> v >> l;
        --u; --v;
        adj[u].push_back({v, l});
        adj[v].push_back({u, l});
    }

    double min_cost = -1.0;
    int optimal_city = -1;

    for (int target_city = 0; target_city < n; ++target_city) {
        double current_cost = 0.0;
        for (int i = 0; i < n; ++i) {
            if (i == target_city) continue;

            vector<int> dist(n, -1);
            vector<int> parent(n, -1);
            vector<bool> visited(n, false);

            dist[i] = 0;
            vector<int> q;
            q.push_back(i);
            visited[i] = true;

            int head = 0;
            while (head < q.size()) {
                int u = q[head++];
                for (auto& edge : adj[u]) {
                    int v = edge.first;
                    int l = edge.second;
                    if (!visited[v]) {
                        visited[v] = true;
                        dist[v] = dist[u] + l;
                        parent[v] = u;
                        q.push_back(v);
                    }
                }
            }

