  vector<bool> busy(n + 1, false);
  vector<int> busy_until(n + 1, 0);

  for (int i = 0; i < q; ++i) {
    int t = tasks[i];
    int k = k_values[i];
    int d = d_values[i];

    vector<int> available_servers;
    for (int j = 1; j <= n; ++j) {
