#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

struct BUT {
    char label;
    BUT *left = nullptr;
    BUT *right = nullptr;
};

BUT* parseBut(const string& s, int& pos) {
    if (pos >= s.length()) return nullptr;

    if (isalpha(s[pos])) {
        BUT* node = new BUT{s[pos]};
        pos++;
        return node;
    }

    if (s[pos] == '(') {
        pos++;
        char label = s[pos];
        pos++;
        if (s[pos] == ')') {
            pos++;
            return new BUT{label};
        } else if (s[pos] == ',') {
            pos++;
            BUT* left = parseBut(s, pos);
            BUT* right = parseBut(s, pos);
            pos++;
            BUT* node = new BUT{label};
            node->left = left;
            node->right = right;
            return node;
        } else {
            BUT* node = new BUT{label};
            node->left = parseBut(s, pos);
            pos++;
            return node;
        }
    }
    return nullptr;
}

void printDiagram(BUT* root, int indent = 0) {
    if (!root) return;

    if (!root->left && !root->right) {
        for (int i = 0; i < indent; ++i) cout << " ";
