        vector<bool> present(n, true);
        present[leaving_students[day] - 1] = false;

        vector<vector<int>> clubs(m);
        for (int i = 0; i < n; ++i) {
            if (present[i]) {
                clubs[c[i] - 1].push_back(i);
            }
