        if (clubs.empty()) {
            cout << 0 << endl;
            continue;
        }


        vector<int> team;


        function<void(int)> solve = [&](int club_index) {
            if (club_index == m) {
                set<int> potentials;
                for (int student_index : team) {
                    potentials.insert(p[student_index]);
