    while (t--) {
        int n;
        cin >> n;

        vector<int> a(n);
        for (int i = 0; i < n; ++i) {
            cin >> a[i];
        }

        string result = "";
        for (int k = 1; k <= n; ++k) {
            vector<int> b(n - k + 1);
            for (int i = 0; i < n - k + 1; ++i) {
                int min_val = a[i];
                for (int j = i + 1; j < i + k; ++j) {
                    min_val = min(min_val, a[j]);
                }
                b[i] = min_val;
            }

            set<int> s;
            bool is_permutation = true;
            for (int val : b) {
                if (val < 1 || val > n) {
                    is_permutation = false;
                    break;
                }
                if (s.count(val)) {
                    is_permutation = false;
                    break;
                }
                s.insert(val);
            }
            if (s.size() != b.size()) {
                is_permutation = false;
            }

            if (is_permutation) {
                result += '1';
            } else {
                result += '0';
            }
        }

        cout << result << endl;
    }

    return 0;
}

