        color_counts[t[k]]++;
      }

      int dominant_color = -1;
      int max_count = -1;
      for (auto const& [color, count] : color_counts) {
        if (count > max_count) {
          max_count = count;
          dominant_color = color;
        } else if (count == max_count && color < dominant_color) {
          dominant_color = color;
        }
      }

      result[dominant_color]++;
    }
  }

  for (int i = 1; i <= n; ++i) {
    cout << result[i] << (i == n ? "" : " ");
  }
  cout << endl;

  return 0;
}

