  }

  long long max_joy = 0;

  for (int i = 0; i < (1 << (n * k)); ++i) {
    if (__builtin_popcount(i) != n * k) continue;

    vector<vector<int>> distributions(n);
    vector<bool> used(n * k, false);
    int card_index = 0;

    for (int j = 0; j < n; ++j) {
